body.script:
//
function checkAccountType(v) {
    document.getElementById('personal-bank-wrap').style.display = v === 'personal' ? 'block' : 'none';
    updateSidebar(v, 1);
}
// Auto-trigger on page load if pre-filled
window.addEventListener('DOMContentLoaded', function() {
    var checked = document.querySelector('input[name=account_type]:checked');
    if(checked) checkAccountType(checked.value);
});

function updateSidebar(accountType, shCount) {
    var sb = document.getElementById('dynamic-steps');
    sb.innerHTML = '';
    if(accountType === 'corporate') {
        var steps = ['Company Information','Corporate Documents'];
        for(var i=1; i<=shCount; i++) steps.push('Shareholder Documents '+i);
        steps.push('Corporate Bank Account','Review application','Payment');
        steps.forEach(function(s, idx) {
            sb.innerHTML += '<div class="progress-step"><div class="step-num">'+(idx+2)+'</div><div class="step-label">'+s+'</div></div>';
        });
    } else {
        sb.innerHTML = '<div class="progress-step"><div class="step-num">2</div><div class="step-label">Shareholder Documents</div></div>' +
            '<div class="progress-step"><div class="step-num">3</div><div class="step-label">Corporate Bank Account</div></div>' +
            '<div class="progress-step"><div class="step-num">4</div><div class="step-label">Review application</div></div>' +
            '<div class="progress-step"><div class="step-num">5</div><div class="step-label">Payment</div></div>';
    }
}


function baValidateStep1() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }
  var at = document.querySelector('input[name="account_type"]:checked');
  if (!at) { showErr('actype_err','Please select Personal or Corporate.'); valid=false; } else hideErr('actype_err');
  if (at && at.value === 'personal') {
    var pb = document.querySelector('[name="preferred_bank"]');
    if (!pb || !pb.value) { showErr('pbank_err','Please select a bank account.'); valid=false; } else hideErr('pbank_err');
  }
  if (valid) document.querySelector('form').submit();
}
//

//
function baValidateStep2() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }
  var files = [
    ['doc_eid','eid_err','EID Copy is required.'],
    ['doc_passport','pass_err','Passport Copy is required.'],
    ['doc_salary','salary_err','Salary Certificate is required.'],
  ];
  files.forEach(function(f) {
    var el = document.querySelector('[name="'+f[0]+'"]');
    if (!el || !el.files || el.files.length === 0) { showErr(f[1], f[2]); valid=false; } else hideErr(f[1]);
  });
  if (valid) document.querySelector('form').submit();
}
//

//
function checkBankReq(v) {
    document.getElementById('bank-provider-wrap').style.display = v === 'yes' ? 'block' : 'none';
}

function baValidateStep3() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }
  var br = document.querySelector('input[name="need_bank_account"]:checked');
  if (!br) { showErr('bankreq_err','Please select Yes or No.'); valid=false; } else hideErr('bankreq_err');
  if (br && br.value === 'yes') {
    var fp = document.querySelector('[name="preferred_financial_provider"]');
    if (!fp || !fp.value) { showErr('finprov_err','Please select a preferred financial assistance service provider.'); valid=false; } else hideErr('finprov_err');
  }
  if (valid) document.querySelector('form').submit();
}
//

//
function checkSpcReg(v) {
    document.getElementById('spc-yes-wrap').style.display = v === 'yes' ? 'block' : 'none';
    document.getElementById('spc-no-wrap').style.display = v === 'no' ? 'block' : 'none';
}

function renderShareholderInputs(count) {
    var container = document.getElementById('sh-name-inputs');
    container.innerHTML = '';
    var n = parseInt(count) || 0;
    for(var i=1; i<=n; i++) {
        var wrap = document.createElement('div');
        wrap.style.marginBottom = '8px';
        var inp = document.createElement('input');
        inp.className = 'field-input';
        inp.type = 'text';
        inp.name = 'shareholder_'+i+'_name';
        inp.placeholder = 'Shareholder '+i+' Name';
        var err = document.createElement('div');
        err.id = 'sh'+i+'name_err';
        err.style.cssText = 'color:red;font-size:12px;display:none;margin-top:4px';
        err.textContent = 'Shareholder '+i+' name must be 3-50 characters.';
        wrap.appendChild(inp);
        wrap.appendChild(err);
        container.appendChild(wrap);
    }
    updateCorpSidebar(n);
}

function updateCorpSidebar(shCount) {
    var sb = document.getElementById('corp-dynamic-steps');
    if(!sb) return;
    var n = parseInt(shCount) || 1;
    var html = '';
    var stepNum = 4;
    for(var i=1; i<=n; i++) {
        html += '<div class="progress-step"><div class="step-num">'+stepNum+'</div><div class="step-label">Shareholder Documents '+i+'</div></div>';
        stepNum++;
    }
    html += '<div class="progress-step"><div class="step-num">'+stepNum+'</div><div class="step-label">Corporate Bank Account</div></div>';
    html += '<div class="progress-step"><div class="step-num">'+(stepNum+1)+'</div><div class="step-label">Review application</div></div>';
    html += '<div class="progress-step"><div class="step-num">'+(stepNum+2)+'</div><div class="step-label">Payment</div></div>';
    sb.innerHTML = html;
}

window.addEventListener('DOMContentLoaded', function() {
    var sc = document.getElementById('sh-count-sel');
    if(sc && sc.value) renderShareholderInputs(sc.value);
    var ms = document.querySelector('input[name="multi_shareholder"]:checked');
    if(ms) checkMultiShareholder(ms.value);
    var spc = document.querySelector('input[name="company_registered_spc"]:checked');
    if(spc) checkSpcReg(spc.value);
});

function checkMultiShareholder(v) {
    document.getElementById('multi-yes-wrap').style.display = v === 'yes' ? 'block' : 'none';
    document.getElementById('multi-no-wrap').style.display = v === 'no' ? 'block' : 'none';
    if(v === 'no') updateCorpSidebar(1);
}

function baValidateStep1Corp() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }

  var spc = document.querySelector('input[name="company_registered_spc"]:checked');
  if (!spc) { showErr('spcreg_err','Please select Yes or No.'); valid=false; } else hideErr('spcreg_err');
  if (spc && spc.value === 'yes') {
    var cn = document.getElementById('company-name-input');
    var cnv = cn ? cn.value.trim() : '';
    if (cnv.length < 3 || cnv.length > 50) { showErr('cname_spc_err','Company name must be 3-50 characters.'); valid=false; } else hideErr('cname_spc_err');
  }
  if (spc && spc.value === 'no') {
    var cm = document.querySelector('[name="company_name_manual"]');
    var cmv = cm ? cm.value.trim() : '';
    if (cmv.length < 3 || cmv.length > 50) { showErr('cname_man_err','Type of company must be 3-50 characters.'); valid=false; } else hideErr('cname_man_err');
  }

  var ms = document.querySelector('input[name="multi_shareholder"]:checked');
  if (!ms) { showErr('multish_err','Please select Yes or No.'); valid=false; } else hideErr('multish_err');

  if (ms && ms.value === 'yes') {
    var sc = document.getElementById('sh-count-sel');
    if (!sc || !sc.value) { showErr('shcount_err','Please select number of shareholders.'); valid=false; } else hideErr('shcount_err');
    if (sc && sc.value) {
      var n = parseInt(sc.value);
      for(var i=1; i<=n; i++) {
        var sf = document.querySelector('[name="shareholder_'+i+'_name"]');
        var sfv = sf ? sf.value.trim() : '';
        if (sfv.length < 3 || sfv.length > 50) { showErr('sh'+i+'name_err','Shareholder '+i+' name must be 3-50 characters.'); valid=false; } else hideErr('sh'+i+'name_err');
      }
    }
  }
  if (ms && ms.value === 'no') {
    var s1 = document.querySelector('[name="shareholder_1_name"]');
    var s1v = s1 ? s1.value.trim() : '';
    if (s1v.length < 3 || s1v.length > 50) { showErr('sh1name_err','Shareholder name must be 3-50 characters.'); valid=false; } else hideErr('sh1name_err');
  }

  if (valid) document.querySelector('form').submit();
}
//

//
function baValidateCorpDocs() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }
  var files = [
    ['doc_business_plan','bp_err','Business Plan is required.'],
    ['doc_business_license','bl_err','Business License is required.'],
    ['doc_formation_cert','fc_err','Formation Certificate is required.'],
    ['doc_share_cert','sc_err','Share Certificate is required.'],
    ['doc_tenancy','ten_err','Tenancy Contract (Ejari) is required.'],
  ];
  files.forEach(function(f) {
    var el = document.querySelector('[name="'+f[0]+'"]');
    if (!el || !el.files || el.files.length === 0) { showErr(f[1], f[2]); valid=false; } else hideErr(f[1]);
  });
  if (valid) document.querySelector('form').submit();
}
