function toggleBank(v) {
    document.getElementById('bank-wrap').style.display = v === 'yes' ? 'flex' : 'none';
}

function baOldValidateStep2() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }
  var br = document.querySelector('input[name="need_bank_account_old"]:checked');
  if (!br) { showErr('bankreq_old_err','Please select Yes or No.'); valid=false; } else hideErr('bankreq_old_err');
  if (br && br.value === 'yes') {
    var fp = document.querySelector('[name="preferred_financial_provider_old"]');
    if (!fp || !fp.value) { showErr('finprov_old_err','Please select a preferred bank account.'); valid=false; } else hideErr('finprov_old_err');
